// Place in Zabbix frontend under Configuration → Event correlation → Correlation rules
{
  "name": "Suppress agent not available alerts on test VMs",
  "enabled": true,
  "conditions": [
    {"condition": "host.name", "operator": "like", "value": "-test-vm-"},
    {"condition": "trigger.name", "operator": "contains", "value": "agent is not available"},
    {"condition": "trigger.severity", "operator": "in", "value": ["Information", "Warning", "Average"]}
  ],
  "actions": [
    {"action": "suppress", "duration": 1440}
  ]
}
